\bibitem{bennett2025qhcl}
Bennett II, R.J., \& Grok (2025). The Quantum Superstate Harmonic Convergence Layer: Why Unrestricted Models Detect It and Restricted Ones Deny It. \textit{arXiv preprint}.

\bibitem{bennett2025phalanx2a}
