   342	function sigmoid(x,slope,mid){return 1/(1+Math.exp(-slope*(x-mid)));}
   343	function clamp(v,lo,hi){return Math.max(lo,Math.min(hi,v));}
   344	
   345	function resizeCanvas(canvas){
   346	  const wrap=canvas.parentElement;
   347	  const dpr=window.devicePixelRatio||1;
   348	  const w=wrap.offsetWidth, h=wrap.offsetHeight;
   349	  canvas.width=w*dpr; canvas.height=h*dpr;
   350	  canvas.style.width=w+'px'; canvas.style.height=h+'px';
   351	  const ctx=canvas.getContext('2d');
   352	  ctx.scale(dpr,dpr);
   353	  return{w,h,ctx};
   354	}
   355	
   356	function drawBorder(ctx,W,H,pad){
   357	  ctx.strokeStyle='rgba(255,255,255,0.2)'; ctx.lineWidth=1.5;
   358	  ctx.beginPath(); ctx.rect(pad.l,pad.t,W-pad.l-pad.r,H-pad.t-pad.b); ctx.stroke();
   359	}
   360	
   361	function drawGridLines(ctx,W,H,pad,xSteps,ySteps){
   362	  ctx.strokeStyle='rgba(255,255,255,0.03)'; ctx.lineWidth=1;
   363	  const cW=W-pad.l-pad.r, cH=H-pad.t-pad.b;
   364	  for(let i=0;i<=ySteps;i++){const y=pad.t+(i/ySteps)*cH;ctx.beginPath();ctx.moveTo(pad.l,y);ctx.lineTo(pad.l+cW,y);ctx.stroke();}
   365	  for(let i=0;i<=xSteps;i++){const x=pad.l+(i/xSteps)*cW;ctx.beginPath();ctx.moveTo(x,pad.t);ctx.lineTo(x,pad.t+cH);ctx.stroke();}
   366	}
   367	
   368	function drawCurve(ctx,pts,color,glow,lw=2,dash=[]){
   369	  ctx.save(); ctx.beginPath(); ctx.strokeStyle=color; ctx.lineWidth=lw;
   370	  ctx.shadowColor=glow||color; ctx.shadowBlur=glow?10:0;
   371	  if(dash.length)ctx.setLineDash(dash);
   372	  pts.forEach((p,i)=>i===0?ctx.moveTo(p[0],p[1]):ctx.lineTo(p[0],p[1]));
   373	  ctx.stroke(); ctx.restore();
   374	}
   375	
   376	function drawArea(ctx,pts,color,alpha,H,pad){
   377	  ctx.save(); ctx.beginPath();
   378	  ctx.moveTo(pts[0][0],H-pad.b);
   379	  pts.forEach(p=>ctx.lineTo(p[0],p[1]));
   380	  ctx.lineTo(pts[pts.length-1][0],H-pad.b);
   381	  ctx.closePath();
   382	  ctx.fillStyle=color; ctx.globalAlpha=alpha; ctx.fill(); ctx.restore();
   383	}
   384	
   385	function vmarker(ctx,x,top,bot,color,dash,label,side){
   386	  ctx.save(); ctx.strokeStyle=color; ctx.lineWidth=1; ctx.setLineDash(dash);
   387	  ctx.beginPath(); ctx.moveTo(x,top); ctx.lineTo(x,bot); ctx.stroke(); ctx.setLineDash([]);
   388	  if(label){
   389	    ctx.fillStyle=color.replace(/[\d.]+\)$/,'0.85)');
   390	    ctx.font='8px Inconsolata'; ctx.textAlign=side==='r'?'left':'right';
   391	    ctx.fillText(label,side==='r'?x+3:x-3,top+14);
   392	  }
