   409	// ═══════════════════════════════════════════
   410	// SIM I — CASCADE / WINTER / SURVIVAL
   411	// ═══════════════════════════════════════════
   412	const YS=2000,YI=2037,YR=2041,YE=2152,YSPAN=152;
   413	const WD=111,CR=5/13,PTD=11.5,FTD=3.0;
   414	const S1={accel:1.0,supp:78,wint:1.0,prep:0.1,lag:8.0,view:'all'};
   415	
   416	function s1c(yr){
   417	  const t=yr-YI, pre=clamp((yr-YS)/(YI-YS)*0.18,0,0.18);
   418	  if(t<=0)return pre;
   419	  return pre+clamp(sigmoid(t/13*S1.accel,8,0.5)*1.02,0,1)*(1-pre);
   420	}
   421	function s1yp(yr){
   422	  if(yr<YI){const nat=clamp(0.22+(yr-YS)/37*0.55,0,0.95),sup=nat*(1-(S1.supp/100)*0.82),noise=Math.sin((yr-YS)*4.1)*0.012+Math.sin((yr-YS)*9.3)*0.006;return clamp(sup+noise,0.02,0.95);}
   423	  const t=yr-YI;
   424	  if(yr<YR){return clamp((0.75+t*0.04)*(1-(S1.supp/100)*0.4),0.1,0.95);}
   425	  const p=yr-YR;
   426	  return clamp(Math.exp(-p*0.5)*0.98+0.35*Math.exp(-p/45)*(p>2?1:p/2),0,1);
   427	}
   428	function s1ta(yr){
   429	  const w=S1.wint;
   430	  if(yr<YI)return 1.4*(yr-YS)/(YI-YS);
   431	  const t=yr-YI;
   432	  if(yr<YR)return 1.4+t*CR*S1.accel;
   433	  const p=yr-YR,war=1.4+(YR-YI)*CR;
   434	  return war-PTD*w*Math.exp(-p/6)*Math.min(1,p/1.5)-FTD*w*(1-Math.exp(-p/8))*Math.exp(-p/85)+war*(1-w*0.92)*Math.exp(-p/20);
   435	}
   436	function s1sp(yr){
   437	  if(yr<=YS)return 1.0;
   438	  if(yr<YI)return clamp(1-(yr-YS)/(YI-YS)*0.05,0.95,1.0);
   439	  const t=yr-YI;
   440	  if(yr<YR)return clamp(0.95-t*CR*0.015,0.88,0.95);
   441	  const par=clamp(0.95-(YR-YI)*CR*0.015,0.88,0.95),p=yr-YR;
   442	  return clamp(par*(1-S1.wint*0.92*(1-Math.exp(-p/2.5)))-(1-S1.wint*0.95)*0.08,0.005,1);
   443	}
   444	function s1pp(yr){if(yr<YR)return 1.0;const p=yr-YR;return clamp(1-0.08*(1-Math.exp(-p/35)),0.88,1.0);}
   445	function s1ph(yr){
   446	  if(yr<YI)return clamp(1-(yr-YS)/(YI-YS)*0.15,0.85,1.0);
   447	  if(yr<YR){const t=yr-YI;return clamp(0.85-t*CR*0.08,0.55,0.85);}
   448	  const p=yr-YR,temp=s1ta(yr);
   449	  return clamp(0.52+(1-clamp(Math.abs(temp)/8,0,1))*0.2+clamp(p/80,0,0.3)+clamp(p/100,0,0.25),0,1);
   450	}
