   452	function s1param(k,v){S1[k]=parseFloat(v);const f={accel:v=>`${parseFloat(v).toFixed(1)}x`,supp:v=>`${v}%`,wint:v=>`${(parseFloat(v)*100).toFixed(0)}%`,prep:v=>`${parseFloat(v).toFixed(2)}%`};if(f[k])document.getElementById('v1_'+k).textContent=f[k](v);drawSim1();}
