   455	function drawSim1(){
   456	  const cv=document.getElementById('c1');
   457	  const{w:W,h:H,ctx}=resizeCanvas(cv);
   458	  const pad={t:24,r:24,b:50,l:56};
   459	  const cW=W-pad.l-pad.r,cH=H-pad.t-pad.b;
   460	  ctx.clearRect(0,0,W,H);ctx.fillStyle='#03040a';ctx.fillRect(0,0,W,H);
   461	  drawGridLines(ctx,W,H,pad,15,10);
   462	  drawBorder(ctx,W,H,pad);
   463	  const toX=yr=>pad.l+((yr-YS)/YSPAN)*cW;
   464	  const toY=v=>pad.t+(1-clamp(v,0,1))*cH;
